options.styles:
.cl-root { display: flex; flex-direction: column; gap: 11px; height: 100%; padding: 2px;
  font-feature-settings: "tnum"; }

/* ── 클러스터 요약 바 ────────────────────────────── */
.cl-bar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 9px 12px; border-radius: 7px;
  background: rgba(204,204,220,0.045); border: 1px solid rgba(204,204,220,0.14); }
.cl-b { display: flex; align-items: baseline; gap: 6px; padding-right: 14px; }
.cl-b + .cl-b { border-left: 1px solid rgba(204,204,220,0.13); padding-left: 14px; }
.cl-bk { font-size: 10.5px; opacity: 0.55; }
.cl-bv { font-size: 19px; font-weight: 700; line-height: 1; }
.cl-bu { font-size: 10.5px; opacity: 0.45; }
.cl-b.warn .cl-bv { color: #e3b341; }
.cl-b.bad .cl-bv { color: #f0554a; }
.cl-b.ok .cl-bv { color: #3fb950; }
.cl-ns-tally { margin-left: auto; display: flex; gap: 4px; flex-wrap: wrap; align-items: center; }
.cl-ns-pill { display: flex; align-items: center; gap: 5px; font-size: 10.5px;
  padding: 2px 8px 2px 6px; border-radius: 10px; background: rgba(204,204,220,0.07); }
.cl-ns-pill b { font-weight: 600; opacity: 0.9; }
.cl-ns-pill em { font-style: normal; opacity: 0.5; font-size: 10px; }

/* ── 노드 카드 ───────────────────────────────────── */
.cl-grid { display: grid; gap: 11px; flex: 1 1 auto; align-content: start;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
.cl-node { position: relative; display: flex; flex-direction: column; gap: 9px; min-width: 0;
  border: 1px solid rgba(204,204,220,0.15); border-radius: 9px; padding: 11px 12px 10px;
  background: linear-gradient(180deg, rgba(204,204,220,0.05), rgba(204,204,220,0.02)); }
.cl-node-h { display: flex; align-items: center; gap: 7px; }
.cl-nd { width: 8px; height: 8px; border-radius: 50%; flex: none; background: #7d8590; }
.cl-nd.ready { background: #3fb950; box-shadow: 0 0 0 3px rgba(63,185,80,0.14); }
.cl-nd.notready { background: #f0554a; box-shadow: 0 0 0 3px rgba(240,85,74,0.16); }
.cl-nm { font-size: 13px; font-weight: 650; letter-spacing: 0.2px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cl-cnt { margin-left: auto; font-size: 12px; font-weight: 700;
  font-family: ui-monospace, SFMono-Regular, monospace; }
.cl-cnt em { font-style: normal; font-weight: 400; opacity: 0.4; font-size: 10.5px; }

/* ── 파드 격자: 정사각형 하나 = 파드 하나, 색 = 네임스페이스 ── */
.cl-cells { display: flex; flex-wrap: wrap; gap: 4px; align-content: flex-start;
  flex: 1 1 auto; min-height: 40px; }
.cl-cell { width: 15px; height: 15px; border-radius: 3px;
  flex: none; cursor: default; outline: none;
  transition: box-shadow 90ms ease; }
.cl-cell:hover, .cl-cell:focus-visible {
  box-shadow: 0 0 0 2px rgba(255,255,255,0.72), 0 0 7px 1px rgba(255,255,255,0.22); }
.cl-none { font-size: 11px; opacity: 0.35; align-self: center; }

/* 네임스페이스 색: 정렬 순서대로 배정해 새로고침해도 안 바뀐다 */
.ns-0 { background: #6e9fff; } .ns-1 { background: #3fb950; }
.ns-2 { background: #a371f7; } .ns-3 { background: #ff9830; }
.ns-4 { background: #37c0c4; } .ns-5 { background: #e3b341; }
.ns-6 { background: #f2779a; } .ns-7 { background: #b0b6c0; }

/* 상태: 정상은 색 그대로, 문제가 있으면 링과 무늬로 덧씌운다 */
.cl-cell.st-notready { box-shadow: inset 0 0 0 2px #e3b341; }
.cl-cell.st-pending { opacity: 0.5; box-shadow: inset 0 0 0 2px #db8a2c;
  animation: clPulse 1.5s ease-in-out infinite; }
.cl-cell.st-failed { box-shadow: inset 0 0 0 2px #f0554a; filter: saturate(0.4) brightness(0.75); }
.cl-cell.st-succeeded { opacity: 0.38; }
.cl-cell.st-unknown { filter: grayscale(1); opacity: 0.5; }
@keyframes clPulse { 0%,100% { opacity: 0.5 } 50% { opacity: 0.22 } }
@media (prefers-reduced-motion: reduce) { .cl-cell.st-pending { animation: none; } }

/* ── 호버 상세: 카드 안쪽에 폭을 맞춘다. 셀에 transform 을 주면 기준점이 셀로 바뀌어 깨진다 ── */
.cl-tip { position: absolute; left: 8px; bottom: 8px;
  width: max-content; max-width: min(230px, calc(100% - 16px));
  display: flex; flex-direction: column; gap: 2px;
  padding: 9px 11px; border-radius: 7px; z-index: 30;
  background: rgba(8,9,12,0.97); border: 1px solid rgba(204,204,220,0.24);
  box-shadow: 0 -6px 22px -8px rgba(0,0,0,0.8);
  font-size: 11px; line-height: 1.45; text-align: left; white-space: normal;
  opacity: 0; visibility: hidden; pointer-events: none;
  transition: opacity 100ms ease, visibility 100ms; }
.cl-cell:hover .cl-tip, .cl-cell:focus-visible .cl-tip {
  opacity: 1; visibility: visible; }
.cl-tip-n { font-size: 11.5px; font-weight: 700; word-break: break-all; line-height: 1.35;
  padding-bottom: 4px; margin-bottom: 2px; border-bottom: 1px solid rgba(204,204,220,0.13); }
.cl-tip-r { display: flex; align-items: center; gap: 6px; }
.cl-tip .cl-dim { opacity: 0.55; }
.cl-tip .cl-num { font-family: ui-monospace, SFMono-Regular, monospace; font-size: 10.5px; opacity: 0.8; }
.cl-swatch { width: 8px; height: 8px; border-radius: 2px; flex: none; }
.cl-sdot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: #3fb950; }
.cl-sdot.st-notready { background: #e3b341; }
.cl-sdot.st-pending { background: #db8a2c; }
.cl-sdot.st-failed { background: #f0554a; }
.cl-sdot.st-succeeded { background: #6e9fff; }
.cl-sdot.st-unknown { background: #7d8590; }

/* ── 노드 푸터: 그 노드 파드들의 사용량 합 / allocatable ── */
.cl-node-f { display: flex; flex-direction: column; gap: 4px; }
.cl-mtr { display: flex; align-items: center; gap: 7px; font-size: 10px; }
.cl-mk { opacity: 0.45; width: 24px; flex: none; letter-spacing: 0.04em; }
.cl-mbar { flex: 1 1 auto; height: 4px; border-radius: 2px; overflow: hidden;
  background: rgba(204,204,220,0.1); }
.cl-mbar i { display: block; height: 100%; border-radius: 2px; background: #6e9fff; }
.cl-mv { flex: none; opacity: 0.6; font-family: ui-monospace, SFMono-Regular, monospace;
  font-size: 10px; min-width: 82px; text-align: right; }

/* ── 범례 ────────────────────────────────────────── */
.cl-legend { display: flex; gap: 6px 15px; flex-wrap: wrap; align-items: center;
  font-size: 10.5px; opacity: 0.62; padding-left: 2px; }
.cl-legend span { display: flex; align-items: center; gap: 5px; }
.cl-legend i.sq { width: 11px; height: 11px; border-radius: 2.5px; flex: none; }
.cl-sep { width: 1px; height: 11px; background: rgba(204,204,220,0.18); }
.cl-empty { font-size: 11px; opacity: 0.6; }

options.helpers:
// renderMode=data 이므로 context.data.data 는 "쿼리별 행 배열"의 배열이다.
// 프레임 순서에 의존하지 않고, 값 쿼리에는 kind 라벨을 붙여 정체를 판별한다.
var raw = context.data || {};
var frames = Array.isArray(raw) ? raw : (Array.isArray(raw.data) ? raw.data : []);
if (frames.length && !Array.isArray(frames[0])) { frames = [frames]; }

function num(r) {
  if (r == null) return NaN;
  if (r.Value !== undefined) return Number(r.Value);
  for (var k in r) { if (k.indexOf('Value') === 0) return Number(r[k]); }
  return NaN;
}

// kind 검사가 먼저다. allocatable/node_ready 도 node 라벨을 갖고 있어 파드 프레임과 헷갈린다
var podRows = [], statRows = [];
frames.forEach(function (rows) {
  if (!Array.isArray(rows) || !rows.length) return;
  if (rows[0].kind !== undefined) { statRows = statRows.concat(rows); }
  else if (rows[0].node !== undefined) { podRows = rows; }
});

var phase = {}, ready = {}, restarts = {}, cpu = {}, mem = {}, age = {};
var allocCpu = {}, allocMem = {}, nodeReady = {}, capacity = {};
statRows.forEach(function (r) {
  var v = num(r);
  switch (r.kind) {
    case 'phase':     if (r.pod) phase[r.pod] = r.phase || 'Unknown'; break;
    case 'ready':     if (r.pod) ready[r.pod] = v === 1; break;
    case 'restarts':  if (r.pod) restarts[r.pod] = v; break;
    case 'cpu':       if (r.pod) cpu[r.pod] = v; break;
    case 'mem':       if (r.pod) mem[r.pod] = v; break;
    case 'age':       if (r.pod) age[r.pod] = v; break;
    case 'alloc_cpu': if (r.node) allocCpu[r.node] = v; break;
    case 'alloc_mem': if (r.node) allocMem[r.node] = v; break;
    case 'node_ready':if (r.node) nodeReady[r.node] = v === 1; break;
    case 'cap_pods':  if (r.node) capacity[r.node] = v; break;
  }
});

var KIND_OF = { ReplicaSet: 'app', Deployment: 'app', StatefulSet: 'stateful',
                DaemonSet: 'daemon', Job: 'job', CronJob: 'job' };
var KIND_LABEL = { app: 'Deployment', stateful: 'StatefulSet', daemon: 'DaemonSet',
                   job: 'Job', bare: '단독 파드' };
var STATE_LABEL = { running: 'Running · Ready', notready: 'Running · Ready 아님',
                    pending: 'Pending', failed: 'Failed',
                    succeeded: 'Succeeded', unknown: 'Unknown' };

function stateOf(pod) {
  var p = phase[pod];
  if (p === 'Running') { return ready[pod] ? 'running' : 'notready'; }
  if (p === 'Pending') return 'pending';
  if (p === 'Failed') return 'failed';
  if (p === 'Succeeded') return 'succeeded';
  return 'unknown';
}

function fmtCpu(v) {
  if (v === undefined || isNaN(v)) return '–';
  if (v >= 100) return Math.round(v) + 'm';
  if (v >= 10) return v.toFixed(0) + 'm';
  if (v >= 1) return v.toFixed(1) + 'm';
  return v.toFixed(2) + 'm';
}
function fmtMem(mib) {
  if (mib === undefined || isNaN(mib)) return '–';
  return mib >= 1024 ? (mib / 1024).toFixed(2) + 'Gi' : Math.round(mib) + 'Mi';
}
function fmtAge(sec) {
  if (sec === undefined || isNaN(sec) || sec < 0) return '–';
  if (sec < 3600) return Math.max(1, Math.round(sec / 60)) + '분';
  if (sec < 86400) return Math.floor(sec / 3600) + '시간';
  return Math.floor(sec / 86400) + '일';
}

// 네임스페이스 색은 이름 정렬 순서로 준다. 해시가 아니라서 새로고침해도 같은 색이 나온다
var namespaces = [];
podRows.forEach(function (r) {
  if (r.pod && r.namespace && namespaces.indexOf(r.namespace) === -1) namespaces.push(r.namespace);
});
namespaces.sort();
var PALETTE_SIZE = 8;
var colorOf = {};
namespaces.forEach(function (ns, i) { colorOf[ns] = i % PALETTE_SIZE; });

function cellOf(r) {
  var owner = r.created_by_name || '';
  var ck = r.created_by_kind || '';
  var kind = KIND_OF[ck] || 'bare';
  var workload = (ck === 'ReplicaSet') ? owner.replace(/-[^-]+$/, '') : owner;
  if (!workload) workload = r.pod;
  var st = stateOf(r.pod);
  return {
    name: r.pod, namespace: r.namespace || '–', color: colorOf[r.namespace] || 0,
    kind: kind, kindLabel: KIND_LABEL[kind], workload: workload,
    state: st, stateLabel: STATE_LABEL[st],
    cpu: fmtCpu(cpu[r.pod]), mem: fmtMem(mem[r.pod]),
    restarts: (restarts[r.pod] === undefined || isNaN(restarts[r.pod])) ? '–' : Math.round(restarts[r.pod]),
    age: fmtAge(age[r.pod]),
    cpuRaw: cpu[r.pod] || 0, memRaw: mem[r.pod] || 0,
    restartsRaw: restarts[r.pod] || 0
  };
}

var groups = {};
podRows.forEach(function (r) {
  if (!r || !r.node) return;
  if (!groups[r.node]) groups[r.node] = [];
  if (r.pod) groups[r.node].push(cellOf(r));
});

var nodeNames = Object.keys(groups).sort();
var total = 0, notReadyTotal = 0, restartTotal = 0, pendingTotal = 0;
var nsTally = {};
nodeNames.forEach(function (n) {
  // 네임스페이스 → 상태 → 이름 순. 같은 네임스페이스가 붙어 있어야 색 덩어리가 읽힌다
  groups[n].sort(function (a, b) {
    if (a.namespace !== b.namespace) return a.namespace.localeCompare(b.namespace);
    if (a.state !== b.state) return a.state === 'running' ? 1 : -1;
    return a.name.localeCompare(b.name);
  });
  groups[n].forEach(function (c) {
    total += 1;
    if (c.state === 'notready' || c.state === 'unknown') notReadyTotal += 1;
    if (c.state === 'pending') pendingTotal += 1;
    restartTotal += c.restartsRaw;
    nsTally[c.namespace] = (nsTally[c.namespace] || 0) + 1;
  });
});

var nodesReady = nodeNames.filter(function (n) { return nodeReady[n] !== false; }).length;

context.handlebars.registerHelper('clusterBar', function () {
  function block(cls, key, value, unit) {
    return '<div class="cl-b' + (cls ? ' ' + cls : '') + '">' +
      '<span class="cl-bk">' + key + '</span><span class="cl-bv">' + value + '</span>' +
      (unit ? '<span class="cl-bu">' + unit + '</span>' : '') + '</div>';
  }
  var html = '<div class="cl-bar">';
  html += block(nodesReady === nodeNames.length ? 'ok' : 'bad', '노드',
                nodesReady, '/ ' + nodeNames.length + ' Ready');
  html += block('', '파드', total, '개');
  html += block(notReadyTotal ? 'warn' : '', 'Ready 아님', notReadyTotal, '');
  html += block(pendingTotal ? 'warn' : '', 'Pending', pendingTotal, '');
  html += block(restartTotal ? 'warn' : '', '누적 재시작', Math.round(restartTotal), '회');

  var tally = Object.keys(nsTally).sort().map(function (ns) {
    return '<span class="cl-ns-pill"><i class="cl-swatch ns-' + (colorOf[ns] || 0) + '"></i>' +
           '<b>' + ns + '</b><em>' + nsTally[ns] + '</em></span>';
  }).join('');
  html += '<div class="cl-ns-tally">' + tally + '</div>';
  return new context.handlebars.SafeString(html + '</div>');
});

context.handlebars.registerHelper('nodeCards', function (options) {
  if (!nodeNames.length) {
    var keys = podRows.length ? Object.keys(podRows[0]) : [];
    return new context.handlebars.SafeString(
      '<div class="cl-empty">노드를 찾지 못했습니다. frames=' + frames.length +
      ' podRows=' + podRows.length + ' 필드=' + JSON.stringify(keys) + '</div>');
  }
  return nodeNames.map(function (node) {
    var cells = groups[node];
    var usedCpu = 0, usedMem = 0;
    cells.forEach(function (c) { usedCpu += c.cpuRaw; usedMem += c.memRaw; });
    var capCpu = (allocCpu[node] || 0) * 1000;             // 코어 → 밀리코어
    var capMem = (allocMem[node] || 0) / 1048576;          // 바이트 → MiB
    var ok = nodeReady[node] !== false;
    return options.fn({
      node: node, count: cells.length, cells: cells,
      capacity: capacity[node] ? Math.round(capacity[node]) : '–',
      readyClass: ok ? 'ready' : 'notready',
      readyLabel: ok ? 'Ready' : 'Ready 아님',
      cpuPct: capCpu ? Math.min(100, Math.round((usedCpu / capCpu) * 100)) : 0,
      memPct: capMem ? Math.min(100, Math.round((usedMem / capMem) * 100)) : 0,
      cpuText: fmtCpu(usedCpu) + ' / ' + (capCpu ? Math.round(capCpu) + 'm' : '–'),
      memText: fmtMem(usedMem) + ' / ' + fmtMem(capMem)
    });
  }).join('');
});

context.handlebars.registerHelper('legend', function () {
  var swatches = namespaces.map(function (ns) {
    return '<span><i class="sq ns-' + colorOf[ns] + '"></i>' + ns + '</span>';
  }).join('');
  return new context.handlebars.SafeString(
    '<div class="cl-legend">' + swatches +
    '<span class="cl-sep"></span>' +
    '<span><i class="sq ns-7" style="box-shadow:inset 0 0 0 2px #e3b341"></i>Ready 아님</span>' +
    '<span><i class="sq ns-7" style="box-shadow:inset 0 0 0 2px #db8a2c;opacity:0.5"></i>Pending</span>' +
    '<span><i class="sq ns-7" style="box-shadow:inset 0 0 0 2px #f0554a;filter:saturate(0.4) brightness(0.75)"></i>Failed</span>' +
    '</div>');
});
